contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint w) public payable {
        require(v != w);

        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint minAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(w); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint minAfterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(minAfterFirst == v && !reverted && minAfterSecond == w);
    }

    receive() external payable {}
}

