pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v, uint256 w) internal {
        vm.assume(v != w);
        try c.SetMinSum(v) {} catch { return; }
        uint256 minAfterFirst;
        try c.MinSum() returns (uint256 __r) { minAfterFirst = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(w) { reverted = false; } catch { reverted = true; }
        uint256 minAfterSecond;
        try c.MinSum() returns (uint256 __r) { minAfterSecond = __r; } catch { return; }
        assertTrue(minAfterFirst == v && !reverted && minAfterSecond == w);
    }

    function testFuzz_run(uint256 v, uint256 w) public {
        _run(v, w);
    }

    receive() external payable {}
}
